        [TestCase(1, 16384)] [TestCase(2, 32768)] public void Load_ValidNrom(int banks, int size) { var c = INesLoader.Load(Rom(banks, 1, 1)); Assert.That(c.MapperNumber, Is.Zero); Assert.That(c.PrgRom.Length, Is.EqualTo(size)); Assert.That(c.ChrRom.Length, Is.EqualTo(8192)); Assert.That(c.Mirroring, Is.EqualTo(MirroringMode.Vertical)); }
        [Test] public void Load_Trainer_SkipsBytes() { var r = Rom(1, 1, 4); r[528] = 0xA5; Assert.That(INesLoader.Load(r).PrgRom[0], Is.EqualTo(0xA5)); }
        [Test] public void Load_InvalidMagic_Throws() { var r = Rom(1, 1); r[0] = 0; Assert.That(() => INesLoader.Load(r), Throws.TypeOf<INesFormatException>().With.Message.Contains("magic")); }
        [Test] public void Load_UnsupportedMapper_Throws() { Assert.That(() => INesLoader.Load(Rom(2, 1, 0x60)), Throws.TypeOf<NotSupportedException>().With.Message.Contains("Mapper 6")); }
        [Test] public void Load_ChrRam_Throws() { Assert.That(() => INesLoader.Load(Rom(1, 0)), Throws.TypeOf<NotSupportedException>().With.Message.Contains("8KB CHR ROM")); }
        [Test] public void Load_Mapper2WithChrRam() { var c = INesLoader.Load(Rom(4, 0, 0x20)); Assert.That(c.MapperNumber, Is.EqualTo(2)); Assert.That(c.HasChrRam, Is.True); Assert.That(c.ChrRom.Length, Is.EqualTo(8192)); }
