        [Test] public void Load_LegacyMapper78HolyDiverBoard() { var c = INesLoader.Load(Rom(8, 16, 0xE0, 0x40)); Assert.That(c.MapperNumber, Is.EqualTo(78)); Assert.That(((PortalNes.Emulator.Mappers.Mapper078)c.Mapper).UsesHolyDiverMirroring, Is.True); }
        [Test] public void Load_LegacyMapper78CosmoCarrierBoard() { var c = INesLoader.Load(Rom(8, 16, 0xE8, 0x40)); Assert.That(((PortalNes.Emulator.Mappers.Mapper078)c.Mapper).UsesHolyDiverMirroring, Is.False); }
