        [Test] public void Load_Mapper154IgnoresFourScreenHeaderFlag() { var c = INesLoader.Load(Rom(8, 16, 0xA8, 0x90)); Assert.That(c.MapperNumber, Is.EqualTo(154)); Assert.That(c.Mapper.MirroringOverride, Is.EqualTo(MirroringMode.SingleScreenLower)); }
