        [Test] public void Load_Mapper206WithBanks() { var c = INesLoader.Load(Rom(8, 8, 0xE0, 0xC0)); Assert.That(c.MapperNumber, Is.EqualTo(206)); Assert.That(c.Mapper, Is.TypeOf<PortalNes.Emulator.Mappers.Mapper206>()); }
        [Test] public void Load_Mapper210WithBanks() { var c = INesLoader.Load(Rom(16, 16, 0x20, 0xD0)); Assert.That(c.MapperNumber, Is.EqualTo(210)); Assert.That(c.HeaderMapperNumber, Is.EqualTo(210)); Assert.That(c.Mapper, Is.TypeOf<PortalNes.Emulator.Mappers.Mapper210>()); }
        [Test] public void Load_Mapper7RejectsHalfPrgBank() { Assert.That(() => INesLoader.Load(Rom(3, 0, 0x70)), Throws.TypeOf<NotSupportedException>().With.Message.Contains("32KB")); }
        [Test] public void Load_RegionFromTvSystemFlag() { var r=Rom(1,1); r[9]=1; Assert.That(INesLoader.Load(r).Region, Is.EqualTo(NesRegion.Pal)); }
        [Test] public void Load_RegionOverrideWinsOverHeader() { var r=Rom(1,1); Assert.That(INesLoader.Load(r, NesRegion.Pal).Region, Is.EqualTo(NesRegion.Pal)); }
        [Test] public void Load_DiskDudeHeader_IgnoresFalseMapperHighBitsAndPalFlag() { var r=Rom(2,4,0x30); var s="DiskDude!"; for(int i=0;i<s.Length;i++) r[7+i]=(byte)s[i]; var c=INesLoader.Load(r); Assert.That(c.MapperNumber, Is.EqualTo(3)); Assert.That(c.HeaderMapperNumber, Is.EqualTo(3)); Assert.That(c.Region, Is.EqualTo(NesRegion.Ntsc)); }
        [Test] public void Load_Nes20StandardMapper() { var r=Rom(8,8,0x40,0x08); var c=INesLoader.Load(r); Assert.That(c.MapperNumber, Is.EqualTo(4)); Assert.That(c.SubmapperNumber, Is.Zero); Assert.That(c.Mapper, Is.TypeOf<PortalNes.Emulator.Mappers.Mapper004>()); }
        [Test] public void Load_Nes20RegionUsesByte12() { var r=Rom(2,4,0x30,0x08); r[12]=1; Assert.That(INesLoader.Load(r).Region, Is.EqualTo(NesRegion.Pal)); }
        [Test] public void Load_Nes20ChrRamUsesDeclaredSize() { var r=Rom(4,0,0x20,0x08); r[11]=7; var c=INesLoader.Load(r); Assert.That(c.HasChrRam, Is.True); Assert.That(c.ChrRom.Length, Is.EqualTo(8192)); }
        [Test] public void Load_Nes20MissingChrRamDeclarationThrows() { var r=Rom(4,0,0x20,0x08); Assert.That(() => INesLoader.Load(r), Throws.TypeOf<NotSupportedException>().With.Message.Contains("CHR RAM")); }
        [Test] public void Load_Nes20Mapper3Submapper1DisablesBusConflicts() { var r=Rom(2,4,0x30,0x08); r[8]=0x10; for(int bank=0;bank<4;bank++) r[16+32768+bank*8192]=(byte)bank; var c=INesLoader.Load(r); c.Mapper.CpuWrite(0x8000,3); Assert.That(c.SubmapperNumber, Is.EqualTo(1)); Assert.That(c.Mapper.PpuRead(0), Is.EqualTo(3)); }
        [Test] public void Load_Nes20Mapper32Submapper1UsesMajorLeagueBoard() { var r=Rom(8,16,0x00,0x28); r[8]=0x10; var c=INesLoader.Load(r); Assert.That(c.SubmapperNumber, Is.EqualTo(1)); Assert.That(c.Mapper.MirroringOverride, Is.EqualTo(MirroringMode.SingleScreenUpper)); }
        [Test] public void Load_Nes20Mapper70Submapper1DisablesBusConflicts() { var r=Rom(8,16,0x60,0x48); r[8]=0x10; var c=INesLoader.Load(r); Assert.That(((PortalNes.Emulator.Mappers.Mapper070)c.Mapper).HasBusConflicts, Is.False); }
        [TestCase(1, false)] [TestCase(3, true)] public void Load_Nes20Mapper78SubmapperSelectsBoard(int submapper, bool holyDiver) { var r=Rom(8,16,0xE0,0x48); r[8]=(byte)(submapper<<4); var c=INesLoader.Load(r); Assert.That(((PortalNes.Emulator.Mappers.Mapper078)c.Mapper).UsesHolyDiverMirroring, Is.EqualTo(holyDiver)); }
        [Test] public void Load_Nes20UnsupportedSubmapperThrowsClearly() { var r=Rom(8,8,0x40,0x08); r[8]=0x10; Assert.That(() => INesLoader.Load(r), Throws.TypeOf<NotSupportedException>().With.Message.Contains("Submapper 1")); }
        private static byte[] Rom(int p, int c, byte f6=0, byte f7=0) { int t=(f6&4)!=0?512:0; var r=new byte[16+t+p*16384+c*8192]; r[0]=(byte)'N';r[1]=(byte)'E';r[2]=(byte)'S';r[3]=0x1A;r[4]=(byte)p;r[5]=(byte)c;r[6]=f6;r[7]=f7;return r; }
    }
}
